<?php
namespace App\Http\Controllers;
use App\Models\{AccountingPeriod,FiscalYear};use App\Services\{PeriodService,YearEndService};use Illuminate\Http\Request;
class PeriodController {public function index(){return view('periods.index',['periods'=>AccountingPeriod::forCompany(auth()->user()->company_id)->orderByDesc('start_date')->get(),'years'=>FiscalYear::forCompany(auth()->user()->company_id)->orderByDesc('year')->get()]);}public function close(AccountingPeriod $period){app(PeriodService::class)->close($period,auth()->id());return back()->with('ok','Period closed.');}public function reopen(Request $r,AccountingPeriod $period){$d=$r->validate(['reason'=>'required|string|max:1000']);app(PeriodService::class)->reopen($period,$r->user()->id,$d['reason']);return back()->with('ok','Period reopened.');}public function closeYear(Request $r,FiscalYear $year){$j=app(YearEndService::class)->close($year,$r->user()->id,$r->input('reason','Year-end close'));return $j?redirect()->route('journals.show',$j):back()->with('ok','Fiscal year closed; no closing journal was required.');}public function reopenYear(Request $r,FiscalYear $year){$d=$r->validate(['date'=>'required|date','reason'=>'required|string|max:1000']);$j=app(YearEndService::class)->reopen($year,$r->user()->id,$d['date'],$d['reason']);return $j?redirect()->route('journals.show',$j):back()->with('ok','Fiscal year reopened.');}}
